import React, { useState, useEffect, useRef, useCallback } from "react";

// ————————————————————————————————————————————————————————————————
// <PayByLeapPhoneHero />
// Drop-in animated phone + card mockup for the PayByLeap landing hero.
//
// Usage in your page:
//   import PayByLeapPhoneHero from "./PayByLeapPhoneHero";
//   ...
//   <div className="your-hero-right-column">
//     <PayByLeapPhoneHero />
//   </div>
//
// Props (all optional):
//   phoneWidth  — phone frame width in px            (default 440)
//   height      — visible height; bottom is cropped   (default 700)
//   showDots    — show scene navigation dots          (default false)
//   autoPlay    — auto-cycle the app screens          (default true)
//   className / style — passed to the root element
//
// The component is fully transparent — it sits on top of whatever
// background your section has. Its footprint is exactly
// (phoneWidth + card overhang) × height; nothing overflows it,
// so it won't cover or block your surrounding UI.
// Flow: CAD wallet → USD wallet → Transfer tap → Confirm → Success.
// Buttons in the screens are genuinely clickable; hovering/tapping
// the card flips USD → NGN black card. Respects reduced motion.
// ————————————————————————————————————————————————————————————————

type ScreenKey = "home" | "action" | "confirm" | "success";
type SceneKey = "cad" | ScreenKey;

interface HotspotDef {
  left: number; // % of the screen image (or window for the baked scene)
  top: number;
  w: number;
  h: number;
  goto: SceneKey;
  label: string;
}

interface SceneDef {
  key: SceneKey;
  img: ScreenKey | null; // null = CAD screen baked into the frame image
  ms: number;
  tap?: { x: number; y: number };
  hotspots: HotspotDef[];
}

export interface PayByLeapPhoneHeroProps {
  /** phone frame width in px (default 440) */
  phoneWidth?: number;
  /** visible height in px; the phone's bottom is cropped (default 700) */
  height?: number;
  /** show scene navigation dots (default false) */
  showDots?: boolean;
  /** auto-cycle the app screens (default true) */
  autoPlay?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

const MAROON = "#7A1E1E";

const IMG = {
  frame:
    "data:image/webp;base64,",
  home: "data:image/jpeg;base64,",
  action:
    "data:image/jpeg;base64,",
  confirm:
    "data:image/jpeg;base64,",
  success:
    "data:image/jpeg;base64,",
  cardUSD:
    "data:image/webp;base64,",
  cardNGN:
    "data:image/webp;base64,",
};

// The mockup's screen window, measured from the frame image (% of frame box)
const WINDOW = { left: 3.947, top: 1.662, w: 91.959, h: 96.711 };
const FRAME_AR = 2828 / 1368; // frame aspect ratio
const CARD_AR = 882 / 1325; // card aspect ratio

// Scenes. img:null = the CAD home screen already baked into the frame.
// Hotspots are % of the overlay image (or of the window for the baked scene).
const SCENES: SceneDef[] = [
  {
    key: "cad",
    img: null,
    ms: 2500,
    hotspots: [
      {
        left: 55,
        top: 18,
        w: 33,
        h: 4.5,
        goto: "home",
        label: "Switch to USD wallet",
      },
      { left: 30, top: 42, w: 17, h: 9, goto: "home", label: "Transfer" },
    ],
  },
  {
    key: "home",
    img: "home",
    ms: 2400,
    hotspots: [
      {
        left: 45,
        top: 13.5,
        w: 22,
        h: 3,
        goto: "cad",
        label: "Switch to CAD wallet",
      },
      { left: 30, top: 39, w: 16, h: 8.5, goto: "confirm", label: "Transfer" },
    ],
  },
  {
    key: "action",
    img: "action",
    ms: 2300,
    tap: { x: 38.15, y: 43.15 },
    hotspots: [
      { left: 30, top: 39, w: 16, h: 8.5, goto: "confirm", label: "Transfer" },
    ],
  },
  {
    key: "confirm",
    img: "confirm",
    ms: 3200,
    hotspots: [
      { left: 6.7, top: 80, w: 86, h: 5.2, goto: "success", label: "Continue" },
    ],
  },
  {
    key: "success",
    img: "success",
    ms: 2800,
    hotspots: [
      {
        left: 10.6,
        top: 66,
        w: 79.3,
        h: 5.2,
        goto: "cad",
        label: "Download receipt",
      },
    ],
  },
];

const KEYS: SceneKey[] = SCENES.map((s) => s.key);

export default function PayByLeapPhoneHero({
  phoneWidth = 440,
  height = 700,
  showDots = false,
  autoPlay = true,
  className = "",
  style = {},
}: PayByLeapPhoneHeroProps) {
  const [sceneKey, setSceneKey] = useState<SceneKey>("cad");
  const [manualUntil, setManualUntil] = useState(0);
  const [tilt, setTilt] = useState({ x: 0, y: 0 });
  const [cardHover, setCardHover] = useState(false);
  const [reduced, setReduced] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  // derived sizes
  const PHONE_W = phoneWidth;
  const PHONE_H = Math.round(PHONE_W * FRAME_AR);
  const isMobile = PHONE_W <= 300;
  const CARD_W = Math.round(PHONE_W * (isMobile ? 0.8 : 0.9));
  const CARD_OVERHANG = Math.round(PHONE_W * (isMobile ? 0.22 : 0.36));
  const ROOT_W = PHONE_W + CARD_OVERHANG + 16;
  const SCREEN_RADIUS = Math.round(PHONE_W * 0.91959 * 0.151);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const fn = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", fn);
    return () => mq.removeEventListener("change", fn);
  }, []);

  const navigate = useCallback((k: SceneKey) => {
    setSceneKey(k);
    setManualUntil(Date.now() + 8000);
  }, []);

  useEffect(() => {
    if (!autoPlay) return;
    const idx = KEYS.indexOf(sceneKey);
    const wait = Math.max(SCENES[idx].ms, manualUntil - Date.now());
    const t = setTimeout(
      () => setSceneKey(KEYS[(idx + 1) % KEYS.length]),
      wait,
    );
    return () => clearTimeout(t);
  }, [sceneKey, manualUntil, autoPlay]);

  // Tilt tracks the cursor over the component only — not the whole page
  const onMove = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (reduced) return;
      const r = rootRef.current?.getBoundingClientRect();
      if (!r) return;
      setTilt({
        x: (e.clientX - r.left) / r.width - 0.5,
        y: (e.clientY - r.top) / r.height - 0.5,
      });
    },
    [reduced],
  );

  const phoneTransform = reduced
    ? "none"
    : `rotateY(${tilt.x * 5}deg) rotateX(${-tilt.y * 4}deg)`;

  const cardTransform = reduced
    ? "none"
    : `translate(${tilt.x * -20}px, ${tilt.y * -14}px)
       translateY(${cardHover ? -8 : 0}px)`;

  return (
    <div
      ref={rootRef}
      className={className}
      onMouseMove={onMove}
      onMouseLeave={() => setTilt({ x: 0, y: 0 })}
      style={{
        // Transparent footprint — sits on YOUR background.
        // clipPath crops ONLY the bottom edge: the card's right overhang,
        // the float headroom and the soft shadows are never cut.
        // flexShrink: 0 stops flex parents from squeezing the fixed
        // footprint (which is what slices the card in half).
        position: "relative",
        width: ROOT_W,
        height,
        boxSizing: "border-box",
        paddingTop: 14,
        flexShrink: 0,
        background: "transparent",
        clipPath: "inset(-140px -180px 0 -180px)",
        ...style,
      }}
    >
      <style>{css}</style>

      <div
        className={reduced ? "" : "pbl-float"}
        style={{ perspective: 1600, position: "relative", width: PHONE_W }}
      >
        {/* Phone: real mockup frame with the CAD screen baked in */}
        <div
          style={{
            width: PHONE_W,
            height: PHONE_H,
            position: "relative",
            transition: "transform .3s ease-out",
            transformStyle: "preserve-3d",
            zIndex: 1,
            transform: phoneTransform,
            filter: "drop-shadow(0 40px 70px rgba(60,20,20,.25))",
          }}
        >
          <img
            src={IMG.frame}
            alt="PayByLeap app in an iPhone"
            style={{
              width: "100%",
              height: "100%",
              display: "block",
              userSelect: "none",
            }}
            draggable={false}
          />
          {/* screen window overlay, clipped to the frame's glass */}
          <div
            style={{
              position: "absolute",
              left: `${WINDOW.left}%`,
              top: `${WINDOW.top}%`,
              width: `${WINDOW.w}%`,
              height: `${WINDOW.h}%`,
              borderRadius: SCREEN_RADIUS,
              overflow: "hidden",
            }}
          >
            {SCENES.filter((s) => s.img !== null).map((s) => (
              <PhoneScene
                key={s.key}
                cfg={s}
                show={s.key === sceneKey}
                reduced={reduced}
                onNavigate={navigate}
              />
            ))}
            {/* hotspots for the baked CAD scene */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                pointerEvents: sceneKey === "cad" ? "auto" : "none",
              }}
            >
              {SCENES[0].hotspots.map((h) => (
                <Hotspot key={h.label} h={h} onNavigate={navigate} />
              ))}
            </div>
          </div>
        </div>

        {/* Card — overlaps the phone; hover/tap flips USD → NGN */}
        <div
          className={reduced ? "" : "pbl-card-drift"}
          style={{
            position: "absolute",
            top: Math.round(PHONE_H * 0.36),
            right: -CARD_OVERHANG,
            zIndex: 2,
            transition: "transform .3s ease-out",
            cursor: "pointer",
            transform: cardTransform,
          }}
          onMouseEnter={() => setCardHover(true)}
          onMouseLeave={() => setCardHover(false)}
          onClick={() => setCardHover((v) => !v)}
        >
          <div style={{ perspective: 1100 }}>
            <div
              style={{
                width: CARD_W,
                height: Math.round(CARD_W * CARD_AR),
                position: "relative",
                transformStyle: "preserve-3d",
                transform: cardHover ? "rotateY(180deg)" : "rotateY(0deg)",
                transition: reduced
                  ? "transform .25s ease"
                  : "transform .7s cubic-bezier(.3,.9,.25,1)",
              }}
            >
              <img
                src={IMG.cardUSD}
                alt="PayByLeap USD card"
                draggable={false}
                style={{
                  position: "absolute",
                  inset: 0,
                  width: "100%",
                  backfaceVisibility: "hidden",
                  WebkitBackfaceVisibility: "hidden",
                  filter: "drop-shadow(0 24px 40px rgba(80,15,15,.35))",
                }}
              />
              <img
                src={IMG.cardNGN}
                alt="PayByLeap NGN card"
                draggable={false}
                style={{
                  position: "absolute",
                  inset: 0,
                  width: "100%",
                  transform: "rotateY(180deg)",
                  backfaceVisibility: "hidden",
                  WebkitBackfaceVisibility: "hidden",
                  filter: "drop-shadow(0 24px 40px rgba(0,0,0,.45))",
                }}
              />
            </div>
          </div>
        </div>
      </div>

      {/* Optional scene dots (off by default) */}
      {showDots && (
        <div
          style={{
            display: "flex",
            gap: 6,
            position: "absolute",
            bottom: 14,
            left: PHONE_W / 2,
            transform: "translateX(-50%)",
            zIndex: 4,
          }}
        >
          {KEYS.map((k) => (
            <button
              key={k}
              onClick={() => navigate(k)}
              style={{
                height: 8,
                borderRadius: 20,
                border: "none",
                cursor: "pointer",
                transition: "all .3s ease",
                padding: 0,
                background: k === sceneKey ? MAROON : "#E4D5CB",
                width: k === sceneKey ? 22 : 8,
              }}
              aria-label={`Show ${k} screen`}
            />
          ))}
        </div>
      )}
    </div>
  );
}

function Hotspot({
  h,
  onNavigate,
}: {
  h: HotspotDef;
  onNavigate: (k: SceneKey) => void;
}) {
  return (
    <button
      aria-label={h.label}
      onClick={() => onNavigate(h.goto)}
      style={{
        position: "absolute",
        left: `${h.left}%`,
        top: `${h.top}%`,
        width: `${h.w}%`,
        height: `${h.h}%`,
        background: "transparent",
        border: "none",
        cursor: "pointer",
        borderRadius: 14,
        padding: 0,
      }}
    />
  );
}

// Overlay scene: real screen export + hotspots.
function PhoneScene({
  cfg,
  show,
  reduced,
  onNavigate,
}: {
  cfg: SceneDef;
  show: boolean;
  reduced: boolean;
  onNavigate: (k: SceneKey) => void;
}) {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        opacity: show ? 1 : 0,
        transform: reduced
          ? "none"
          : show
            ? "translateX(0)"
            : "translateX(26px)",
        transition: reduced
          ? "opacity .2s"
          : "opacity .45s ease, transform .45s cubic-bezier(.22,.9,.3,1)",
        pointerEvents: show ? "auto" : "none",
      }}
    >
      <div style={{ position: "relative" }}>
        <img
          src={IMG[cfg.img as ScreenKey]}
          alt={`PayByLeap app — ${cfg.key} screen`}
          style={{ width: "100%", display: "block" }}
          draggable={false}
        />

        {cfg.tap && show && !reduced && (
          <span
            className="pbl-tap"
            style={{
              position: "absolute",
              width: 48,
              height: 48,
              borderRadius: "50%",
              background: "rgba(255,255,255,.45)",
              border: "2px solid rgba(255,255,255,.9)",
              boxShadow: "0 4px 18px rgba(0,0,0,.18)",
              pointerEvents: "none",
              zIndex: 2,
              left: `calc(${cfg.tap.x}% - 24px)`,
              top: `calc(${cfg.tap.y}% - 24px)`,
            }}
          />
        )}

        {cfg.hotspots.map((h) => (
          <Hotspot key={h.label} h={h} onNavigate={onNavigate} />
        ))}
      </div>
    </div>
  );
}

const css = `
  @keyframes pblFloat {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-10px); }
  }
  .pbl-float { animation: pblFloat 5.5s ease-in-out infinite; }

  @keyframes pblDrift {
    0%, 100% { margin-top: 0; }
    50% { margin-top: 12px; }
  }
  .pbl-card-drift { animation: pblDrift 4.4s ease-in-out infinite; }

  @keyframes pblTap {
    0%, 45% { opacity: 0; transform: scale(1.5); }
    62% { opacity: .95; transform: scale(1); }
    76% { opacity: .95; transform: scale(.78); }
    100% { opacity: 0; transform: scale(1.1); }
  }
  .pbl-tap { animation: pblTap 2.2s ease-out both; }

  @media (prefers-reduced-motion: reduce) {
    .pbl-float, .pbl-card-drift, .pbl-tap { animation: none !important; }
  }
`;
